import os
import json
import argparse
from typing import Any, Optional, List
from collections import deque

class HyperLogLog:
    """
    A configuration-aware queue with dynamic resizing capabilities.

    Supports configuration from files, environment variables, and CLI arguments.
    Provides queue operations: enqueue, dequeue, and peek.
    """

    def __init__(self, config: Optional[dict] = None):
        """Initialize with optional config dict."""
        self._queue = deque()
        self._max_size = config.get('max_size', 1000)
        self._resize_factor = config.get('resize_factor', 2)

    @classmethod
    def from_file(cls, filepath: str) -> 'HyperLogLog':
        """Create instance from config file."""
        with open(filepath, 'r') as f:
            config = json.load(f)
        return cls(config)

    @classmethod
    def from_env(cls, prefix: str = "HLL") -> 'HyperLogLog':
        """Create instance from environment variables."""
        config = {}
        for key, value in os.environ.items():
            if key.startswith(prefix):
                config[key[len(prefix)+1:].lower()] = value
        return cls(config)

    @classmethod
    def from_args(cls, args: Optional[List[str]] = None) -> 'HyperLogLog':
        """Create instance from CLI arguments."""
        parser = argparse.ArgumentParser()
        parser.add_argument('--max-size', type=int, default=1000)
        parser.add_argument('--resize-factor', type=int, default=2)
        parsed = parser.parse_args(args)
        return cls(vars(parsed))

    def enqueue(self, item: Any) -> None:
        """Add item to queue, resize if needed."""
        if len(self._queue) >= self._max_size:
            self._resize()
        self._queue.append(item)

    def dequeue(self) -> Any:
        """Remove and return front item."""
        if not self._queue:
            raise IndexError("Queue is empty")
        return self._queue.popleft()

    def peek(self) -> Any:
        """Return front item without removing."""
        if not self._queue:
            raise IndexError("Queue is empty")
        return self._queue[0]

    def _resize(self) -> None:
        """Resize queue capacity."""
        self._max_size *= self._resize_factor
